<!doctype html>
<html lang="{{ str_replace('_', '-', app()->getLocale()) }}">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{{ __('composer-monitor::messages.title') }}</title>
<style>
:root{color-scheme:light;--bg:#f4f6fb;--surface:#fff;--ink:#182230;--muted:#758195;--line:#e8edf4;--accent:#6658d3;--accent-soft:#f0edff;--green:#16845b;--amber:#a96508;--red:#c13c48;--shadow:0 10px 35px rgba(26,39,68,.06)}
:root[data-theme=dark]{color-scheme:dark;--bg:#11151d;--surface:#191f2b;--ink:#edf1f7;--muted:#9ba7b8;--line:#2b3443;--accent:#a69aff;--accent-soft:#2a2543;--green:#5dd6a3;--amber:#f0bb69;--red:#ff8790;--shadow:0 10px 35px rgba(0,0,0,.18)}
@media(prefers-color-scheme:dark){:root:not([data-theme=light]){color-scheme:dark;--bg:#11151d;--surface:#191f2b;--ink:#edf1f7;--muted:#9ba7b8;--line:#2b3443;--accent:#a69aff;--accent-soft:#2a2543;--green:#5dd6a3;--amber:#f0bb69;--red:#ff8790;--shadow:0 10px 35px rgba(0,0,0,.18)}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
.shell{max-width:1440px;margin:auto;padding:42px 34px 70px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:34px}.brand{display:flex;align-items:center;gap:14px}.mark{display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:var(--accent);color:white;font-weight:800;font-size:19px}h1{font-size:23px;letter-spacing:-.7px;margin:0;font-weight:750}.sub{color:var(--muted);margin:3px 0 0}.actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.last,.muted{color:var(--muted);font-size:12px}.btn{border:0;background:var(--accent);color:#fff;padding:11px 17px;border-radius:10px;font-weight:650;cursor:pointer}.btn:disabled{opacity:.65;cursor:wait}.notice{padding:13px 16px;border:1px solid var(--line);background:var(--surface);border-radius:12px;margin-bottom:18px}.notice.error{border-color:var(--red);color:var(--red)}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:25px}.stat,.panel{background:var(--surface);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow)}.stat{padding:20px 21px}.stat-label{color:var(--muted);font-size:12px;font-weight:600}.stat-value{font-size:30px;letter-spacing:-1px;font-weight:750;margin-top:7px}.stat-foot{font-size:11px;color:var(--muted);margin-top:2px}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--accent);margin-right:7px}.panel{margin-top:18px;overflow:hidden}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:19px 22px;border-bottom:1px solid var(--line)}h2{font-size:15px;margin:0;font-weight:700}.count{color:var(--muted);font-size:12px;margin-left:8px}.search,.select{border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:9px;padding:9px 12px;outline:none}.search{width:min(270px,45vw)}table{border-collapse:collapse;width:100%;min-width:720px}th{text-align:left;padding:11px 22px;color:var(--muted);font-size:10px;letter-spacing:.07em;text-transform:uppercase;background:var(--bg);font-weight:700}td{padding:14px 22px;border-top:1px solid var(--line);vertical-align:middle}tbody tr:hover{background:var(--accent-soft)}.table-wrap{overflow-x:auto}.pkg{font-weight:650}.desc{font-size:11px;color:var(--muted);max-width:380px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.version{font:12px ui-monospace,SFMono-Regular,monospace;color:var(--muted)}.pill{display:inline-flex;align-items:center;padding:4px 8px;border-radius:6px;font-size:10px;font-weight:700;background:var(--accent-soft);color:var(--accent)}.pill.amber{color:var(--amber)}.pill.red{color:var(--red)}.empty{padding:28px;text-align:center;color:var(--muted)}.link{color:var(--accent);text-decoration:none}.link:hover{text-decoration:underline}.footer{margin-top:26px;text-align:center;color:var(--muted);font-size:11px}.alert-row{padding:14px 20px;border-top:1px solid var(--line)}.alert-row strong{display:block}.alert-row small{color:var(--muted)}
@media(max-width:850px){.shell{padding:25px 18px 50px}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.topbar{align-items:flex-start}}@media(max-width:520px){.topbar{flex-direction:column}.actions{width:100%}.stats{gap:10px}.stat{padding:15px}.stat-value{font-size:25px}.panel-head{align-items:flex-start;flex-direction:column}.search{width:100%}}
</style>
</head><body><div class="shell">
@include('composer-monitor::dashboard')
<div class="footer">Composer Monitor · {{ count($packages) }} dependencies scanned</div>
</div></body></html>
